import{_ as a,o as l,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020-04-14 :: Ceph Crimson Meeting","description":"","frontmatter":{"title":"2020-04-14 :: Ceph Crimson Meeting","date":"2020-04-14T00:00:00.000Z","updated":"2020-04-29T00:00:00.000Z","tags":["Ceph","分布式存储","Crimson","开发与调试","单元测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-04-14_-_-_Ceph_Crimson_Meeting.md","filePath":"posts/2020/2020-04-14_-_-_Ceph_Crimson_Meeting.md","lastUpdated":1780460162000}'),t={name:"posts/2020/2020-04-14_-_-_Ceph_Crimson_Meeting.md"};function o(n,i,s,h,u,d){return l(),e("div",null,[...i[0]||(i[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph分布式存储系统crimson后端的开发与调试" tabindex="-1">会议主题：Ceph分布式存储系统Crimson后端的开发与调试 <a class="header-anchor" href="#会议主题-ceph分布式存储系统crimson后端的开发与调试" aria-label="Permalink to &quot;会议主题：Ceph分布式存储系统Crimson后端的开发与调试&quot;">​</a></h4><h4 id="参会人员-ceph研发团队成员" tabindex="-1">参会人员：Ceph研发团队成员 <a class="header-anchor" href="#参会人员-ceph研发团队成员" aria-label="Permalink to &quot;参会人员：Ceph研发团队成员&quot;">​</a></h4><h4 id="会议时间-2020年4月14日" tabindex="-1">会议时间：2020年4月14日 <a class="header-anchor" href="#会议时间-2020年4月14日" aria-label="Permalink to &quot;会议时间：2020年4月14日&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>对象类功能的实现与调试</strong></p><ul><li>讨论了在对象类中新功能的实现，尤其是在PG后端的实现。</li><li>强调了在对象类中实现新功能时，需要相应的函数来支持几何操作。</li></ul></li><li><p><strong>消息传递系统的配置与测试</strong></p><ul><li>讨论了消息传递系统的硬编码配置问题，以及如何移除这些配置。</li><li>提到了单元测试已验证了消息传递系统的更改，但发现了一些需要在主分支上修复的问题。</li></ul></li><li><p><strong>Crimson后端状态与调试</strong></p><ul><li>讨论了Crimson后端在达到后端状态时遇到的问题，以及如何解决这些问题。</li><li>提到了Crimson中事件处理和恢复操作的调度方式与传统OSD不同，需要进一步优化。</li></ul></li><li><p><strong>Scrubbing引擎的改进</strong></p><ul><li>讨论了如何重构现有的Scrubbing代码，以便更好地支持未来的开发和测试。</li><li>强调了重构代码以提高其可测试性和可维护性将非常有价值。</li></ul></li><li><p><strong>SeaStar反应器的单元测试框架</strong></p><ul><li>讨论了如何使用SeaStar反应器进行单元测试，以及如何简化测试框架。</li><li>强调了简化单元测试编写的措施将对开发有利。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续推进对象类功能的实现和调试工作。</li><li>解决消息传递系统在主分支上的问题，并确保所有测试通过。</li><li>优化Crimson后端的调度机制，确保事件处理和恢复操作的正确性。</li><li>重构Scrubbing代码，提高其可测试性和可维护性。</li><li>完善SeaStar反应器的单元测试框架，简化测试流程。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>完成对象类功能的实现，并进行详细的测试。</li><li>修复消息传递系统在主分支上的问题，并提交PR。</li><li>对Crimson后端进行进一步的优化和调试，确保其稳定性和性能。</li><li>开始重构Scrubbing代码，并进行单元测试。</li><li>完善SeaStar反应器的单元测试框架，并推广使用。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>所有开发工作应遵循Ceph的开发规范和最佳实践。</li><li>定期进行代码审查和性能测试，确保代码质量和系统性能。</li><li>保持团队内部的沟通和协作，及时解决开发过程中遇到的问题。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议于具体时间结束，感谢所有参会人员的积极参与和贡献。</li></ul>',14)])])}const _=a(t,[["render",o]]);export{c as __pageData,_ as default};
